"""matplotlib.path — Path stubs."""

import sys as _sys
import numpy as _np


_path_warned = set()

def _path_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _path_warned:
        _path_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] path.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Path:
    """Stub matplotlib Path."""
    __getattr__ = _path_getattr_fallback

    STOP = 0
    MOVETO = 1
    LINETO = 2
    CURVE3 = 3
    CURVE4 = 4
    CLOSEPOLY = 79

    NUM_VERTICES_FOR_CODE = {STOP: 1, MOVETO: 1, LINETO: 1,
                              CURVE3: 2, CURVE4: 3, CLOSEPOLY: 1}

    code_type = _np.uint8

    def __init__(self, vertices, codes=None, _interpolation_steps=1,
                 closed=False, readonly=False):
        self.vertices = _np.asarray(vertices)
        self.codes = codes
        self._interpolation_steps = _interpolation_steps
        self._closed = closed
        self._readonly = readonly
        self._simplify_threshold = 1.0 / 9.0
        self._should_simplify = False

    @property
    def simplify_threshold(self): return self._simplify_threshold
    @simplify_threshold.setter
    def simplify_threshold(self, t): self._simplify_threshold = float(t)

    @property
    def has_nonfinite(self):
        try:    return bool(_np.any(~_np.isfinite(self.vertices)))
        except Exception: return False

    @property
    def should_simplify(self): return self._should_simplify
    @should_simplify.setter
    def should_simplify(self, b): self._should_simplify = bool(b)

    @property
    def readonly(self): return self._readonly

    @staticmethod
    def unit_circle():
        t = _np.linspace(0, 2 * _np.pi, 64)
        verts = _np.column_stack([_np.cos(t), _np.sin(t)])
        return Path(verts)

    @staticmethod
    def unit_rectangle():
        return Path([(0, 0), (1, 0), (1, 1), (0, 1), (0, 0)])

    @staticmethod
    def unit_regular_polygon(numVertices):
        t = _np.linspace(0, 2 * _np.pi, numVertices + 1)
        verts = _np.column_stack([_np.cos(t), _np.sin(t)])
        return Path(verts)

    @staticmethod
    def unit_circle_righthalf():
        t = _np.linspace(-_np.pi/2, _np.pi/2, 32)
        verts = _np.column_stack([_np.cos(t), _np.sin(t)])
        return Path(verts)

    def contains_point(self, point, transform=None, radius=0.0):
        """Point-in-polygon test using the standard ray-casting (even-
        odd-rule) algorithm. ``radius`` expands the polygon outward by
        that distance so near-edge points count as inside.
        """
        verts = _np.asarray(self.vertices)
        if transform is not None:
            verts = transform.transform(verts)
        if len(verts) < 3:
            if radius <= 0:
                return False
            return bool(_np.any(_np.linalg.norm(verts - _np.asarray(point),
                                                axis=1) <= radius))
        x, y = point[0], point[1]
        n = len(verts); inside = False; j = n - 1
        for i in range(n):
            xi, yi = verts[i]; xj, yj = verts[j]
            if (yi > y) != (yj > y):
                x_cross = xi + (y - yi) * (xj - xi) / (yj - yi + 1e-30)
                if x < x_cross:
                    inside = not inside
            j = i
        if inside:
            return True
        # Edge-distance check if radius > 0.
        if radius > 0:
            for k in range(n):
                p0 = verts[k]; p1 = verts[(k + 1) % n]
                d = p1 - p0
                length_sq = float(d @ d)
                if length_sq == 0:
                    continue
                t = max(0.0, min(1.0, float((_np.asarray(point) - p0) @ d) / length_sq))
                proj = p0 + t * d
                if _np.linalg.norm(proj - _np.asarray(point)) <= radius:
                    return True
        return False

    def contains_points(self, points, transform=None, radius=0.0):
        """Vectorised :meth:`contains_point` for many query points at once."""
        pts = _np.asarray(points)
        return _np.array([self.contains_point(pt, transform=transform,
                                               radius=radius) for pt in pts])

    def intersects_path(self, other, filled=True):
        """True if any vertex of ``other`` lies inside ``self`` (when
        ``filled``), or if any edge of either path crosses any edge of
        the other. O(n*m) — good enough for the small paths user code
        typically passes.
        """
        ours = _np.asarray(self.vertices)
        theirs = _np.asarray(getattr(other, 'vertices', other))
        if filled:
            for pt in theirs:
                if self.contains_point(pt):
                    return True
            for pt in ours:
                if hasattr(other, 'contains_point') and other.contains_point(pt):
                    return True
        # Edge-vs-edge crossing test.
        def _ccw(A, B, C):
            return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])
        for i in range(len(ours) - 1):
            for j in range(len(theirs) - 1):
                p1, p2 = ours[i], ours[i + 1]
                p3, p4 = theirs[j], theirs[j + 1]
                if _ccw(p1, p3, p4) != _ccw(p2, p3, p4) and \
                   _ccw(p1, p2, p3) != _ccw(p1, p2, p4):
                    return True
        return False

    def get_extents(self, transform=None):
        """Return the axis-aligned bounding bbox of the (optionally
        transformed) vertices as a :class:`matplotlib.transforms.Bbox`.
        Real matplotlib returns a Bbox; upstream's old return shape
        (4-tuple) is preserved by Bbox's ``extents`` property."""
        verts = self.vertices
        if transform is not None:
            try:    verts = transform.transform(verts)
            except Exception: pass
        verts = _np.asarray(verts)
        if len(verts) == 0:
            from matplotlib.transforms import Bbox
            return Bbox.from_extents(0, 0, 0, 0)
        xs, ys = verts[:, 0], verts[:, 1]
        from matplotlib.transforms import Bbox
        return Bbox.from_extents(float(xs.min()), float(ys.min()),
                                  float(xs.max()), float(ys.max()))

    def transformed(self, transform):
        """Return a new Path with vertices passed through ``transform``."""
        try:
            new_verts = transform.transform(self.vertices)
            return Path(new_verts, codes=self.codes,
                        _interpolation_steps=self._interpolation_steps,
                        closed=self._closed)
        except Exception:
            return self

    def intersects_bbox(self, bbox, filled=True):
        """True if the path's extent overlaps ``bbox``. Approximation:
        we test bounding-box overlap rather than exact path-vs-box."""
        try:
            ext = self.get_extents()
            return not (ext.x1 < bbox.x0 or ext.x0 > bbox.x1 or
                         ext.y1 < bbox.y0 or ext.y0 > bbox.y1)
        except Exception:
            return False

    def intersects_path(self, other, filled=True):
        """True if this path's extent overlaps ``other``'s extent."""
        try:
            return self.intersects_bbox(other.get_extents(), filled=filled)
        except Exception:
            return False

    def contains_path(self, other, transform=None):
        """Return True if every vertex of ``other`` lies inside this
        path (containment test, not strict subset of segments)."""
        try:
            verts = other.vertices if transform is None \
                    else transform.transform(other.vertices)
            return all(self.contains_point(v) for v in verts)
        except Exception:
            return False

    def iter_segments(self, transform=None, remove_nans=True, clip=None,
                       snap=False, stroke_width=1.0, simplify=None,
                       curves=True, sketch=None):
        """Yield ``(vertices, code)`` tuples for each segment. Real
        matplotlib's iterator; we emit one segment per vertex."""
        verts = self.vertices
        if transform is not None:
            try: verts = transform.transform(verts)
            except Exception: pass
        codes = self.codes if self.codes is not None else \
                [Path.MOVETO] + [Path.LINETO] * (len(verts) - 1)
        for v, c in zip(verts, codes):
            if remove_nans and not all(_np.isfinite(v)):
                continue
            yield v, c

    def cleaned(self, transform=None, remove_nans=True, clip=None,
                 simplify=False, curves=True, stroke_width=1.0,
                 snap=False, sketch=None):
        return self.transformed(transform) if transform is not None else self

    def to_polygons(self, transform=None, width=0, height=0, closed_only=True):
        verts = self.vertices if transform is None \
                else transform.transform(self.vertices)
        return [verts.tolist()] if len(verts) > 0 else []

    def copy(self):
        return Path(self.vertices.copy(),
                    codes=(self.codes.copy() if self.codes is not None else None),
                    _interpolation_steps=self._interpolation_steps,
                    closed=self._closed)

    def __copy__(self):
        return self.copy()

    def __deepcopy__(self, memo):
        return self.copy()

    def __len__(self):
        return len(self.vertices)

    def __iter__(self):
        for v in self.vertices: yield tuple(v)


