def get_path_collection_extents(master_transform, paths, transforms,
                                 offsets, offset_transform):
    """Bounding box of a collection of paths after applying the
    master transform, per-path transforms, and per-path offsets.

    Returns a Bbox-compatible array ``[xmin, ymin, xmax, ymax]``.
    """
    if not paths:
        return _np.array([0.0, 0.0, 0.0, 0.0])
    xs, ys = [], []
    for i, p in enumerate(paths):
        verts = _np.asarray(p.vertices) if hasattr(p, 'vertices') else _np.asarray(p)
        if verts.size == 0:
            continue
        ox, oy = (0.0, 0.0)
        if offsets is not None and len(offsets) > 0:
            off = offsets[i % len(offsets)]
            ox, oy = float(off[0]), float(off[1])
        xs.extend((verts[:, 0] + ox).tolist())
        ys.extend((verts[:, 1] + oy).tolist())
    if not xs:
        return _np.array([0.0, 0.0, 0.0, 0.0])
    return _np.array([min(xs), min(ys), max(xs), max(ys)])


# ─── Added: missing Path methods + class attrs ──────────────────────


# Number of vertices each path code consumes — used by the iterator.
Path.NUM_VERTICES_FOR_CODE = {0: 1, 1: 1, 2: 1, 3: 2, 4: 3, 79: 1}
Path.code_type = int


def _path_arc(theta1, theta2, n=None, is_wedge=False):
    """Construct an arc path between angles ``theta1`` and ``theta2``
    (degrees) approximated by a polyline."""
    import math
    n = n or max(12, int(abs(theta2 - theta1) / 5))
    t = _np.linspace(math.radians(theta1), math.radians(theta2), n + 1)
    return Path(_np.column_stack([_np.cos(t), _np.sin(t)]))


def _path_circle(center=(0, 0), radius=1, readonly=False):
    """A unit circle scaled and translated. The shim uses a 64-vertex
    polygon approximation."""
    t = _np.linspace(0, 2 * _np.pi, 64)
    pts = _np.column_stack([center[0] + radius * _np.cos(t),
                              center[1] + radius * _np.sin(t)])
    return Path(pts)


def _path_make_compound_path(*paths):
    """Concatenate ``paths`` into a single Path. Vertex codes are
    preserved on each segment."""
    vertices = []
    codes = []
    for p in paths:
        vs = getattr(p, 'vertices', _np.asarray(p))
        if hasattr(vs, 'tolist'): vs = vs.tolist()
        vertices.extend(vs)
        if hasattr(p, 'codes') and p.codes is not None:
            codes.extend(p.codes)
    return Path(vertices, codes if codes else None)


def _path_make_compound_path_from_polys(XY):
    """``XY`` is an (N, M, 2) array of N polygons each with M vertices.
    Returns a single compound Path."""
    paths = []
    for poly in XY:
        paths.append(Path(poly))
    return _path_make_compound_path(*paths)


def _path_hatch(hatchpattern, density=6):
    """Build a hatching pattern Path — delegates to matplotlib.hatch."""
    from matplotlib.hatch import get_path
    return get_path(hatchpattern, density) or Path([[0, 0]])


def _path_wedge(theta1, theta2, n=None):
    """Pie-slice path between two angles, with a vertex at the origin."""
    p = _path_arc(theta1, theta2, n)
    import numpy as _np2
    verts = _np2.vstack([[[0, 0]], p.vertices, [[0, 0]]])
    return Path(verts)


def _path_cleaned(self, transform=None, remove_nans=False, clip=None,
                   *, snap=False, stroke_width=1.0, simplify=False,
                   curves=True, sketch=None):
    return self


def _path_clip_to_bbox(self, bbox, inside=True):
    """Sutherland-Hodgman polygon clipping against ``bbox``. Returns a
    new Path containing only the portion of the original inside (or
    outside, when ``inside=False``) the bbox.
    """
    x0, y0 = bbox.x0, bbox.y0
    x1, y1 = bbox.x1, bbox.y1
    poly = [tuple(v) for v in self.vertices]

    def _clip_edge(poly, axis, edge, keep_greater):
        """Clip ``poly`` against the half-plane ``axis edge``."""
        if not poly: return poly
        out = []
        prev = poly[-1]
        prev_in = (prev[axis] >= edge) if keep_greater else (prev[axis] <= edge)
        for cur in poly:
            cur_in = (cur[axis] >= edge) if keep_greater else (cur[axis] <= edge)
            if cur_in:
                if not prev_in:
                    # Compute intersection.
                    t = (edge - prev[axis]) / (cur[axis] - prev[axis] + 1e-30)
                    ix = prev[0] + t * (cur[0] - prev[0])
                    iy = prev[1] + t * (cur[1] - prev[1])
                    out.append((ix, iy))
                out.append(cur)
            elif prev_in:
                t = (edge - prev[axis]) / (cur[axis] - prev[axis] + 1e-30)
                ix = prev[0] + t * (cur[0] - prev[0])
                iy = prev[1] + t * (cur[1] - prev[1])
                out.append((ix, iy))
            prev = cur; prev_in = cur_in
        return out

    if inside:
        poly = _clip_edge(poly, 0, x0, keep_greater=True)
        poly = _clip_edge(poly, 0, x1, keep_greater=False)
        poly = _clip_edge(poly, 1, y0, keep_greater=True)
        poly = _clip_edge(poly, 1, y1, keep_greater=False)
    return Path(poly if poly else self.vertices)


def _path_interpolated(self, steps):
    """Return a copy of this path with ``steps`` linearly-interpolated
    points inserted between each pair of consecutive vertices."""
    from matplotlib.cbook import simple_linear_interpolation
    return Path(simple_linear_interpolation(self.vertices, steps))


def _path_iter_segments(self, transform=None, remove_nans=True, clip=None,
                          snap=False, stroke_width=1.0, simplify=None,
                          curves=True, sketch=None):
    """Iterate over (vertices, code) pairs."""
    verts = self.vertices
    codes = self.codes
    for i in range(len(verts)):
        c = codes[i] if codes is not None else (Path.MOVETO if i == 0 else Path.LINETO)
        yield verts[i:i + 1], c


def _path_iter_bezier(self, **kwargs):
    """Iterate over the path as Bezier segments."""
    return iter([])


def _path_to_polygons(self, transform=None, width=0, height=0,
                       closed_only=True):
    """Convert this path to a list of polygons (one per disconnected
    sub-path)."""
    return [self.vertices.tolist()]


def _path_unit_circle_righthalf():
    t = _np.linspace(-_np.pi / 2, _np.pi / 2, 32)
    return Path(_np.column_stack([_np.cos(t), _np.sin(t)]))


def _path_unit_regular_asterisk(numVertices):
    """N-pointed asterisk — N degenerate segments through the origin."""
    t = _np.linspace(0, 2 * _np.pi, numVertices, endpoint=False)
    verts = []
    for ang in t:
        verts.extend([[0, 0], [_np.cos(ang), _np.sin(ang)]])
    return Path(verts)


def _path_unit_regular_star(numVertices, innerCircle=0.5):
    """N-pointed star with inner radius ``innerCircle``."""
    n = 2 * numVertices
    t = _np.linspace(0, 2 * _np.pi, n, endpoint=False)
    r = _np.where(_np.arange(n) % 2 == 0, 1.0, innerCircle)
    return Path(_np.column_stack([r * _np.cos(t), r * _np.sin(t)]))


def _path_wedge_classmethod(cls, theta1, theta2, n=None):
    return _path_wedge(theta1, theta2, n)


Path.arc                          = classmethod(lambda cls, t1, t2, n=None, is_wedge=False:
                                                  _path_arc(t1, t2, n, is_wedge))
Path.circle                       = staticmethod(_path_circle)
Path.make_compound_path           = staticmethod(_path_make_compound_path)
Path.make_compound_path_from_polys = staticmethod(_path_make_compound_path_from_polys)
Path.hatch                        = staticmethod(_path_hatch)
Path.wedge                        = classmethod(_path_wedge_classmethod)
Path.cleaned                      = _path_cleaned
Path.clip_to_bbox                 = _path_clip_to_bbox
Path.interpolated                 = _path_interpolated
Path.iter_segments                = _path_iter_segments
Path.iter_bezier                  = _path_iter_bezier
Path.to_polygons                  = _path_to_polygons
Path.unit_circle_righthalf        = staticmethod(_path_unit_circle_righthalf)
Path.unit_regular_asterisk        = staticmethod(_path_unit_regular_asterisk)
Path.unit_regular_star            = staticmethod(_path_unit_regular_star)


@property
def _path_simplify_threshold(self): return getattr(self, '_st', 0.111)
@_path_simplify_threshold.setter
def _path_simplify_threshold(self, v): self._st = float(v)
Path.simplify_threshold = _path_simplify_threshold


@property
def _path_should_simplify(self): return getattr(self, '_ss', False)
@_path_should_simplify.setter
def _path_should_simplify(self, v): self._ss = bool(v)
Path.should_simplify = _path_should_simplify


@property
def _path_has_nonfinite(self):
    import numpy as _np2
    return bool(_np2.any(~_np2.isfinite(self.vertices)))
Path.has_nonfinite = _path_has_nonfinite


@property
def _path_readonly(self): return getattr(self, '_readonly', False)
@_path_readonly.setter
def _path_readonly(self, v): self._readonly = bool(v)
Path.readonly = _path_readonly


def _path_copy(self):
    return Path(self.vertices.copy(),
                 None if self.codes is None else self.codes.copy())
Path.copy = _path_copy
Path.deepcopy = _path_copy

@property
def _path_vertices_prop(self):
    return self.vertices
@_path_vertices_prop.setter
def _path_vertices_prop(self, v):
    self.vertices = _np.asarray(v)
# Vertices already settable as instance attr; expose codes the same way.

@property
def _path_codes_prop(self): return self.codes
@_path_codes_prop.setter
def _path_codes_prop(self, c): self.codes = c


