@property
def _p_vertices(self):  return self.__dict__.get('vertices')
@_p_vertices.setter
def _p_vertices(self, v): self.__dict__['vertices'] = _np.asarray(v)
Path.vertices = _p_vertices

@property
def _p_codes(self): return self.__dict__.get('codes')
@_p_codes.setter
def _p_codes(self, c): self.__dict__['codes'] = c
Path.codes = _p_codes


def _p_contains_path(self, other, transform=None):
    """True if every vertex of ``other`` lies inside ``self``."""
    verts = _np.asarray(getattr(other, 'vertices', other))
    if transform is not None:
        verts = transform.transform(verts)
    for pt in verts:
        if not self.contains_point(pt):
            return False
    return True


def _p_intersects_bbox(self, bbox, filled=True):
    """True if any vertex of the path is inside ``bbox`` or any edge of
    the path crosses ``bbox``."""
    x0, y0 = bbox.x0, bbox.y0
    x1, y1 = bbox.x1, bbox.y1
    for vx, vy in self.vertices:
        if x0 <= vx <= x1 and y0 <= vy <= y1:
            return True
    if filled:
        # Bbox corners inside the path?
        for cx, cy in ((x0, y0), (x1, y0), (x1, y1), (x0, y1)):
            if self.contains_point((cx, cy)):
                return True
    # Edge-crossing test against the bbox rectangle.
    box_path = Path([(x0, y0), (x1, y0), (x1, y1), (x0, y1), (x0, y0)])
    return self.intersects_path(box_path, filled=False)
Path.contains_path   = _p_contains_path
Path.intersects_bbox = _p_intersects_bbox
